shellCommands.command:
/bin/bash -lc "cat > app/globals.css <<'EOF'
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Lora:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&display=swap');

:root { --paper: #faf9f6; --ink: #30372f; --muted: #85877c; --rust: #b65d3c; --rust-dark: #9c492c; --line: #e7e6df; --sage: #6f8065; --serif: 'Lora', Georgia, serif; --sans: 'DM Sans', Arial, sans-serif; }
* { box-sizing: border-box; }
body { margin: 0; background: var(--paper); color: var(--ink); font-family: var(--sans); font-size: 14px; -webkit-font-smoothing: antialiased; }
button, input, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; }
button:disabled { cursor: default; opacity: .55; }
button, a, input, textarea { outline-offset: 4px; }
:focus-visible { outline: 2px solid var(--rust); }
h1, h2, h3, p { margin: 0; }
button, .button, a { transition: background-color .18s, color .18s, border-color .18s, transform .18s; }
.site-header { border-bottom: 1px solid var(--line); background: #fdfcf9; }
.header-inner { max-width: 1280px; height: 88px; margin: auto; padding: 0 64px; display: flex; align-items: center; justify-content: space-between; }
.brand { display: flex; align-items: center; gap: 11px; font-family: var(--serif); font-size: 31px; font-weight: 600; letter-spacing: -1.9px; }
.brand-icon { width: 36px; height: 37px; border-radius: 9px; background: var(--rust); color: #fffaf3; display: grid; place-items: center; }
.brand-dot { color: var(--rust); margin-left: -11px; }
nav { display: flex; align-items: center; gap: 33px; }
.nav-library { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 550; }
.nav-library:hover { color: var(--rust); }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 1px solid var(--rust); background: var(--rust); color: #fffdf9; border-radius: 5px; padding: 13px 20px; font-size: 12px; line-height: 18px; font-weight: 550; box-shadow: 0 2px 2px #6f42230b; }
.button:hover:not(:disabled) { background: var(--rust-dark); border-color: var(--rust-dark); }
.button-small { padding: 9px 14px; }
.button-secondary { background: #fffdfa; border-color: #d9dace; color: var(--ink); box-shadow: none; }
.button-secondary:hover:not(:disabled) { background: #f0f1e9; border-color: #bfc4b7; }
.button-ghost { background: transparent; border-color: var(--line); color: #636b5e; box-shadow: none; }
.button-ghost:hover:not(:disabled) { background: #eeeee7; border-color: #d8dbcf; }
.page-container { max-width: 1280px; margin: auto; padding: 0 64px; }
.library-page { min-height: calc(100vh - 169px); }
.library-intro { display: flex; align-items: center; justify-content: space-between; padding: 56px 0 47px; border-bottom: 1px solid var(--line); margin-bottom: 35px; gap: 25px; }
.eyebrow { font-size: 10px; font-weight: 600; letter-spacing: 1.9px; color: var(--rust); display: flex; align-items: center; gap: 7px; line-height: 1.8; }
.eyebrow > span:not(.optional) { height: 5px; width: 5px; background: var(--rust); border-radius: 50%; }
h1 { font-family: var(--serif); font-size: 40px; line-height: 1.3; letter-spacing: -1.55px; font-weight: 400; }
.library-intro h1 { margin: 12px 0 12px; }
h1 em { font-weight: 400; color: var(--sage); }
.intro-description { color: #7e8277; font-size: 13px; line-height: 1.7; }
.library-counts { display: flex; gap: 33px; padding-right: 6px; padding-top: 15px; }
.library-counts > div { min-width: 58px; display: flex; flex-direction: column; gap: 8px; }
.library-counts > div + div { padding-left: 33px; border-left: 1px solid var(--line); }
.count-number { font-family: var(--serif); font-size: 35px; line-height: 1; color: #4e5649; }
.library-counts > div > span:last-child { display: flex; gap: 6px; align-items: center; font-size: 10px; color: var(--muted); }
.status-dot { width: 5px; height: 5px; background: var(--rust); border-radius: 50%; display: inline-block; flex-shrink: 0; }
.status-dot.green { background: #84927a; }
.section-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 22px; }
.section-title { display: flex; align-items: center; gap: 10px; }
.section-title > svg { color: #777f6c; }
.section-title h2 { font-size: 17px; letter-spacing: -.25px; font-weight: 550; }
.count-badge { display: grid; place-items: center; padding: 2px 7px; min-width: 21px; border-radius: 5px; background: #efeee8; color: #87897c; font-size: 10px; margin-left: 1px; }
.section-caption { font-size: 11px; color: #8c8e83; }
.reading-empty { min-height: 312px; border: 1px solid #e4e3d8; border-radius: 9px; background: #f1f2eb; display: flex; justify-content: center; align-items: center; padding: 32px 50px; gap: 78px; overflow: hidden; position: relative; }
.reading-empty::before { content: ''; position: absolute; width: 200px; height: 200px; border: 1px solid #d7dbcb55; border-radius: 50%; left: -148px; bottom: -80px; }
.empty-copy { max-width: 330px; }
.empty-copy .eyebrow { color: #848b76; font-size: 8px; letter-spacing: 1.6px; }
.empty-copy h3 { font-family: var(--serif); font-weight: 400; font-size: 25px; letter-spacing: -.7px; margin: 10px 0 11px; line-height: 1.4; }
.empty-copy > p:not(.eyebrow) { color: #7c8273; font-size: 12px; line-height: 1.9; }
.empty-copy .button { margin-top: 23px; padding: 11px 17px; }
.empty-footnote { display: block; color: #96998c; font-size: 10px; margin-top: 13px; }
.books-illustration { width: 255px; height: 230px; position: relative; flex-shrink: 0; }
.illustration-orbit { position: absolute; border-radius: 50%; background: #e6e9de; width: 208px; height: 208px; left: 24px; top: 8px; }
.illustration-orbit::after { content: ''; width: 229px; height: 229px; position: absolute; border: 1px dashed #d6dcca; border-radius: 50%; top: -11px; left: -11px; }
.illustration-book { position: absolute; width: 82px; height: 133px; border-radius: 2px 4px 4px 2px; bottom: 23px; box-shadow: 3px 5px 8px #3d463420, inset 5px 0 0 #ffffff12, inset 7px 0 0 #0000000d; padding: 20px 9px 10px 14px; text-align: center; font-family: var(--serif); }
.illustration-book i { position: absolute; width: 43px; border-bottom: 1px solid #ffffff44; bottom: 13px; left: 21px; }
.illustration-book span { display: block; }
.book-sage { left: 21px; transform: rotate(-13deg); background: #7f8c71; color: #eeeede; height: 139px; bottom: 23px; padding-top: 29px; font-size: 11px; line-height: 1.8; }
.book-sage::after { content: ''; width: 23px; height: 33px; border: 1px solid #d6dfc4aa; border-radius: 50% 50% 0 0; position: absolute; left: 34px; top: 81px; }
.book-rust { left: 92px; background: #ba694c; color: #fff2d8; height: 167px; z-index: 2; font-size: 10px; line-height: 1.7; padding-top: 25px; }
.book-rust em { display: inline-block; font-size: 23px; font-weight: 400; line-height: 1.4; }
.book-rust::after { content: '✳'; position: absolute; bottom: 23px; left: 37px; font-size: 21px; color: #e4b08d; }
.book-cream { left: 165px; background: #e9d7ad; color: #65745f; transform: rotate(11deg); font-size: 13px; padding-top: 13px; line-height: 1.15; height: 126px; bottom: 21px; }
.book-cream em { font-size: 15px; line-height: 1.2; }
.book-cream i { border-color: #87947866; }
.illustration-shelf { width: 260px; position: absolute; left: 1px; bottom: 16px; height: 2px; background: #b9c1a9; border-radius: 20px; box-shadow: 0 8px 10px #65765210; }
.little-spark { position: absolute; color: #9aa689; z-index: 3; }
.spark-one { left: 27px; top: 26px; font-size: 24px; }
.spark-two { right: 6px; top: 51px; font-size: 18px; }
.finished-section { margin-top: 38px; }
.finished-empty { display: flex; align-items: center; gap: 19px; padding: 27px 28px; min-height: 105px; border: 1px dashed #d9ddcf; border-radius: 7px; background: #fcfbf8; }
.finished-empty-icon { display: grid; place-items: center; width: 44px; height: 44px; background: #f0f1e9; border-radius: 50%; color: #879079; flex-shrink: 0; }
.finished-empty h3 { font-family: var(--serif); font-size: 15px; font-weight: 400; margin-bottom: 7px; }
.finished-empty p { color: #8b8e80; font-size: 11px; line-height: 1.7; }
.finished-empty-line { flex: 1; }
.finished-spark { color: #b0b69f; }
.library-bottom { padding: 28px 0 36px; display: flex; justify-content: space-between; align-items: center; gap: 20px; color: #929587; font-size: 10px; }
.library-bottom > span { display: flex; align-items: center; gap: 8px; }
.tiny-leaf { font-size: 23px; color: #a6ad98; }
.library-bottom a { display: flex; align-items: center; gap: 7px; }
.library-bottom a:hover { color: var(--rust); }
.site-footer { border-top: 1px solid var(--line); max-width: 1152px; margin: auto; display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 23px 0; color: #9b9d92; font-size: 10px; }
.site-footer > div { display: flex; gap: 16px; align-items: center; }
.footer-brand { font-family: var(--serif); font-size: 20px; letter-spacing: -1px; color: #7d8374; }
.footer-note { display: flex; align-items: center; gap: 8px; }
.book-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
.book-card { min-width: 0; background: #fffefa; border: 1px solid var(--line); border-radius: 7px; overflow: hidden; }
.book-display { height: 223px; display: flex; align-items: center; justify-content: center; background: #efeee7; position: relative; transition: background .2s; overflow: hidden; }
.book-card-link:hover .book-display { background: #e9e8df; }
.book-card-link:hover .book-cover { transform: rotate(-3deg) translateY(-4px); }
.book-cover { width: 116px; height: 164px; background: #6a7864; color: #f3e9d1; border-radius: 2px 5px 5px 2px; position: relative; box-shadow: 7px 10px 16px #33382624, 1px 1px 1px #33382633; transition: transform .25s; flex-shrink: 0; overflow: hidden; }
.cover-spine { position: absolute; top: 0; bottom: 0; left: 0; width: 9px; border-right: 1px solid #00000015; background: linear-gradient(90deg,#ffffff12,transparent 35%,#00000010); }
.cover-inner { height: 100%; padding: 16px 12px 13px 18px; display: flex; flex-direction: column; align-items: center; text-align: center; }
.cover-label { font-size: 4px; letter-spacing: 1.1px; opacity: .75; border-bottom: 1px solid #ffffff30; padding-bottom: 6px; width: 100%; }
.cover-title { margin-top: 13px; font-family: var(--serif); font-size: 15px; line-height: 1.25; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; overflow-wrap: anywhere; }
.cover-author { margin-top: auto; font-size: 5px; letter-spacing: .6px; text-transform: uppercase; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cover-art { display: flex; gap: 3px; height: 31px; margin-top: auto; margin-bottom: 7px; align-items: center; }
.cover-art span { width: 15px; height: 28px; border: 1px solid currentColor; border-radius: 20px 20px 0 0; opacity: .5; }
.cover-art span:nth-child(2) { transform: rotate(180deg); }
.cover-1 { background: #ac6248; color: #ffead0; }
.cover-2 { background: #e4d3af; color: #5e6757; }
.cover-3 { background: #53666c; color: #f2e5c9; }
.cover-4 { background: #787080; color: #f4e3d6; }
.cover-2 .cover-label { border-bottom-color: #5e675733; }
.book-open-icon { display: grid; place-items: center; position: absolute; right: 14px; bottom: 13px; border-radius: 50%; width: 28px; height: 28px; color: #8b9281; background: #faf9f580; }
.book-info { padding: 18px 19px 14px; }
.book-info h3 { font-family: var(--serif); font-size: 17px; font-weight: 500; line-height: 1.5; overflow-wrap: anywhere; }
.book-info p { color: var(--muted); font-size: 11px; margin-top: 5px; overflow-wrap: anywhere; }
.book-card-footer { border-top: 1px solid #eeede7; margin: 0 19px; padding: 13px 0; display: flex; justify-content: space-between; gap: 10px; align-items: center; flex-wrap: wrap; }
.text-button { display: inline-flex; align-items: center; justify-content: center; gap: 5px; border: 0; background: transparent; color: #78836b; font-size: 10px; padding: 0; }
.text-button:hover { color: var(--rust); }
.notes-indicator { font-size: 9px; color: #a0a394; }
.finished-label { display: flex; align-items: center; gap: 5px; color: #7f8a71; font-size: 10px; }
.add-card { border: 1px dashed #d9dcce; min-height: 300px; border-radius: 7px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; color: #7d8671; background: #f5f5ef; font-size: 13px; }
.add-card:hover { background: #eeefe5; border-color: #afb8a0; }
.add-card small { font-size: 10px; color: #9b9f8f; margin-top: -5px; }
.add-circle { border-radius: 50%; border: 1px solid #d6ddca; height: 44px; width: 44px; display: grid; place-items: center; margin-bottom: 4px; }
.inner-page { padding-top: 32px; padding-bottom: 64px; min-height: calc(100vh - 170px); }
.back-link { font-size: 11px; display: inline-flex; align-items: center; gap: 7px; color: #808573; }
.back-link:hover { color: var(--rust); }
.form-page-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 100px; margin-top: 40px; }
.form-page-grid h1 { margin: 9px 0 10px; font-size: 37px; }
.book-form { margin-top: 31px; }
.field { margin-bottom: 22px; }
.field > label, .status-field legend { display: block; font-size: 12px; font-weight: 550; margin-bottom: 9px; }
.field label > span:not(.optional) { color: var(--rust); font-size: 11px; }
.optional { color: #9a9d91; font-size: 10px; font-weight: 400; margin-left: 5px; }
input:not([type=radio]):not([type=hidden]), textarea { width: 100%; border: 1px solid #dcdfd2; border-radius: 5px; background: #fffefa; color: var(--ink); padding: 13px 14px; font-size: 12px; line-height: 1.7; }
input::placeholder, textarea::placeholder { color: #a3a699; opacity: 1; }
input:focus, textarea:focus { border-color: #b8bfab; outline: 2px solid #dce1d160; outline-offset: 1px; }
textarea { resize: vertical; min-height: 120px; }
.field-hint { font-size: 10px; color: #929788; margin-top: 7px; }
.status-field { margin: 0 0 23px; padding: 0; border: 0; }
.status-options { display: flex; gap: 12px; }
.status-option { display: flex; align-items: center; gap: 8px; padding: 13px 12px; border: 1px solid #e0e2d8; border-radius: 5px; flex: 1; color: #8c9181; font-size: 11px; cursor: pointer; }
.status-option.selected { border-color: #b4bea5; background: #f0f2e8; color: #657356; }
.status-option input { width: 13px; height: 13px; margin: 0 2px 0 0; accent-color: #758265; }
.form-actions { display: flex; align-items: center; gap: 24px; border-top: 1px solid var(--line); padding-top: 22px; margin-top: 25px; }
.cancel-link { color: #96998c; font-size: 12px; }
.cancel-link:hover { color: var(--ink); }
.form-aside { align-self: stretch; border-radius: 9px; background: #f0f1e9; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 40px 20px; text-align: center; }
.aside-rule { width: 38px; height: 1px; background: #c5cbb9; margin: 31px 0 24px; }
.form-aside > p { font-family: var(--serif); font-style: italic; font-size: 21px; line-height: 1.65; color: #6c775f; }
.form-aside > span { font-size: 8px; letter-spacing: 1.5px; color: #929b83; margin-top: 18px; }
.aside-note { font-size: 10px; line-height: 1.9; color: #9ca28f; margin-top: 49px; }
.detail-topbar { display: flex; justify-content: space-between; align-items: center; gap: 20px; }
.detail-topbar .button { padding: 9px 13px; font-size: 11px; }
.book-detail { margin-top: 37px; display: grid; grid-template-columns: 280px 1fr; align-items: center; gap: 53px; }
.detail-cover-display { padding: 35px; background: #eeeee5; height: 325px; display: flex; align-items: center; justify-content: center; border-radius: 8px; }
.cover-large { width: 169px; height: 239px; box-shadow: 9px 13px 20px #303a3428, 1px 1px 1px #33382633; }
.cover-large .cover-inner { padding: 24px 18px 20px 25px; }
.cover-large .cover-label { font-size: 6px; padding-bottom: 9px; }
.cover-large .cover-title { font-size: 23px; margin-top: 19px; }
.cover-large .cover-author { font-size: 7px; }
.cover-large .cover-art { height: 45px; margin-bottom: 13px; }
.cover-large .cover-art span { width: 22px; height: 40px; }
.status-pill { font-size: 10px; padding: 6px 9px; display: inline-flex; gap: 6px; align-items: center; border-radius: 5px; background: #f4eae0; color: #ad694b; }
.status-pill.finished { background: #eaf0e3; color: #73815f; }
.status-pill.finished .status-dot { background: #81916d; }
.detail-info h1 { margin-top: 18px; max-width: 710px; font-size: 36px; overflow-wrap: anywhere; }
.detail-author { margin-top: 12px; font-size: 15px; color: #7c8471; overflow-wrap: anywhere; line-height: 1.6; }
.detail-dates { margin: 26px 0 23px; display: flex; flex-direction: column; gap: 8px; color: #959989; font-size: 10px; }
.detail-dates p { display: flex; align-items: center; gap: 7px; }
.detail-info .button { font-size: 11px; padding: 10px 14px; }
.notes-section { margin-top: 42px; }
.notes-section .section-heading { margin-bottom: 18px; }
.notes-section textarea { background: #fffefa; line-height: 2; font-size: 13px; padding: 22px; min-height: 230px; border-color: #e0e2d6; }
.notes-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 13px; }
.notes-toolbar > span { font-size: 10px; color: #9a9f8e; }
.saved-message { color: #72825e; display: flex; align-items: center; gap: 5px; }
.share-control { position: relative; }
.share-fallback { position: absolute; top: 46px; right: 0; width: min(330px, 85vw); background: #fffefa; padding: 16px; border: 1px solid var(--line); border-radius: 7px; box-shadow: 0 10px 30px #30372f12; z-index: 10; }
.share-fallback label { display: block; font-size: 11px; margin-bottom: 8px; }
.error-message { color: #a23f2a; font-size: 11px; line-height: 1.7; }
.status-form .error-message { margin-top: 8px; }
.form-error { background: #faece6; border-radius: 5px; padding: 12px; }
.missing-page { min-height: calc(100vh - 170px); padding-top: 100px; padding-bottom: 100px; text-align: center; }
.missing-page > svg { color: #8e9a7e; margin-bottom: 23px; }
.missing-page .eyebrow { justify-content: center; margin-bottom: 12px; }
.missing-page h1 { font-size: 33px; }
.missing-page > p:not(.eyebrow) { color: #8a907f; max-width: 500px; margin: 17px auto 27px; line-height: 1.9; }
.sr-only, .skip-link:not(:focus) { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip-link:focus { position: fixed; padding: 15px; background: var(--paper); z-index: 100; top: 10px; left: 10px; }
.spin { animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
@media (min-width: 1400px) { .library-intro { padding-top: 67px; padding-bottom: 55px; } .reading-empty { min-height: 340px; } }
